function maximumTotalDamage(power) {
  const count = new Map();
  for (const p of power) {
    count.set(p, (count.get(p) ?? 0) + 1);
  }
  const values = [...count.keys()].sort((a, b) => a - b);
  const m = values.length;
  const dp = new Array(m + 1).fill(0);
  let j = 0;

  for (let i = 0; i < m; i++) {
    while (values[j] < values[i] - 2) {
      j++;
    }
    const take = dp[j] + values[i] * count.get(values[i]);
    dp[i + 1] = Math.max(dp[i], take);
  }
  return dp[m];
}

