function maximumTotalDamage(power) {
  // Try every subset of spells and keep the best one where no two chosen damages differ by 1 or 2.
  const n = power.length;
  const chosen = [];
  let best = 0;
  const search = (index, total) => {
    if (index === n) { best = Math.max(best, total); return; }
    search(index + 1, total);
    const x = power[index];
    if (chosen.every(y => Math.abs(x - y) === 0 || Math.abs(x - y) > 2)) {
      chosen.push(x);
      search(index + 1, total + x);
      chosen.pop();
    }
  };
  search(0, 0);
  return best;
}

