function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const mode = Math.floor(rand() * 3);
  const value = () => {
    if (mode === 0) return 1 + Math.floor(rand() * (size === 'large' ? 3000 : 12));
    if (mode === 1) return 1000000000 - Math.floor(rand() * (size === 'large' ? 4000 : 12));
    return rand() < 0.5 ? 1 + Math.floor(rand() * 1000000000) : 1 + Math.floor(rand() * (size === 'large' ? 500 : 8));
  };
  return [Array.from({ length: n }, value)];
}
